.toolbar {
  display: flex;      /* children flow left to right */
  align-items: center; /* one centre line for all of them */
  gap: 16px;
}

.toolbar > * {
  /* every direct child is a flex item now */
}

.page {
  display: flex;
  flex-direction: column; /* main axis is now vertical */
  min-height: 100vh;      /* needed before vertical distribution works */
}

.page__main {
  flex: 1; /* takes the free height, pushing the footer down */
}

.chips {
  display: flex;
  flex-wrap: wrap;   /* items drop to a second line instead of shrinking */
  gap: 8px;
}

.chip {
  flex: 0 0 auto;    /* a chip keeps its label width */
  padding: 4px 10px;
}

.row {
  display: flex;
  justify-content: space-between; /* first at start, last at end */
  align-items: center;
}

/* One item to the far end, without justify-content: */
.row__action {
  margin-left: auto;
}

.media {
  display: flex;
  align-items: flex-start; /* stop the image from stretching to text height */
  gap: 12px;
}

.media__img {
  flex: none;   /* the picture keeps its size */
  width: 64px;
  height: 64px;
  object-fit: cover;
}

.tags {
  display: flex;
  flex-wrap: wrap;      /* required, otherwise align-content does nothing */
  align-content: center; /* centres the block of lines vertically */
  min-height: 200px;
  gap: 8px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px 24px; /* 12px between rows, 24px between columns */
}

.flex-row {
  display: flex;
  gap: 16px; /* replaces margins between items */
}

.split {
  display: flex;
  gap: 16px;
}

.split__aside { flex-grow: 1; } /* one third of the extra width */
.split__main  { flex-grow: 2; } /* two thirds */

.field-row {
  display: flex;
  gap: 8px;
}

.field-row__input {
  flex: 1 1 auto;
  min-width: 0;   /* allows shrinking below the longest word */
}

.field-row__button {
  flex-shrink: 0; /* the button keeps its padding and label */
}

.card {
  flex-basis: 260px; /* start at 260px */
  flex-grow: 1;      /* then take a share of what is left */
  flex-shrink: 1;    /* then give way when the row overflows */
}

/* auto falls back to width, then to content size */
.card--content-sized {
  flex-basis: auto;
}

.row {
  display: flex;
}

.row__badge {
  order: -1; /* painted first, still last in the DOM */
}

.row__hint {
  order: 1; /* painted last */
}

.cards {
  display: flex;
  align-items: stretch; /* cards share the tallest height */
}

.cards__note {
  align-self: flex-start; /* this one stays at its own height */
  background: #fffbe6;
}

.navbar {
  display: flex;
  align-items: center;
  gap: 24px;
}

.navbar__signin {
  margin-left: auto; /* everything after this sits at the far end */
}

.layout {
  display: grid; /* one column by default, items stack */
  gap: 16px;
}

.layout > * {
  /* each direct child occupies one cell in source order */
}

.layout {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr); /* sidebar plus fluid main */
  gap: 24px;
}

/* fr shares what is left after fixed tracks and gaps */
.halves {
  display: grid;
  grid-template-columns: 1fr 2fr; /* one third, two thirds */
}

.equal {
  display: grid;
  grid-template-columns: repeat(3, 1fr); /* three equal columns */
  gap: 16px;
}

.mixed {
  display: grid;
  grid-template-columns: 80px repeat(2, 1fr) 120px;
  gap: 8px;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}

/* 0 as the minimum lets the track shrink below its content */
.two {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 2fr);
}

/* stretches: one item fills the whole row */
.stretch {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}

/* keeps card sized slots, empty space stays at the right */
.fixed-slots {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 16px;
}

.page {
  display: grid;
  grid-template-rows: auto 1fr auto; /* header, scroll area, footer */
  min-height: 100vh;
}

.page__main {
  overflow: auto; /* the 1fr row scrolls instead of stretching the page */
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  grid-auto-rows: minmax(220px, auto); /* equal tiles with a height floor */
  gap: 16px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.grid__banner {
  grid-column: 1 / -1; /* full width whatever the column count */
}

.grid__wide {
  grid-column: span 2; /* two cells from wherever it lands */
  grid-row: 2;         /* second row, one cell tall */
}

.layout {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-areas:
    "header  header"
    "sidebar main";
  gap: 16px;
}

.layout__header  { grid-area: header; }
.layout__sidebar { grid-area: sidebar; }
.layout__main    { grid-area: main; }

.panel {
  grid-area: 2 / 1 / 3 / 3; /* row 2 to 3, columns 1 to 3 */
}

.card--featured {
  grid-area: feature; /* matches grid-template-areas */
}

.hero {
  display: grid;
  place-items: center; /* one child, centred on both axes */
  min-height: 60vh;
}

/* track alignment is a different pair:
   justify-content and align-content move the tracks themselves */

.news {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: 120px;
  grid-auto-flow: row dense;
  gap: 16px;
}

.news__feature {
  grid-column: span 2;
  grid-row: span 2; /* leaves a hole that dense fills with later items */
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  grid-auto-rows: minmax(260px, auto);
  gap: 24px;
  padding: 24px;
}

.gallery .card {
  display: grid;
  grid-template-rows: 160px 1fr; /* image band, then text */
  overflow: hidden;
  border-radius: 12px;
  background: #fff;
}

.gallery .card img {
  width: 100%;
  height: 100%;
  object-fit: cover; /* crop, do not distort */
  display: block;
}
